class LateError : public Error {
private:
  String _message;
public:
  LateError(String _message) : _message(_message) {
  }
  
  LateError(String fieldName) : _message(dart_string("Field '") + fieldName.toString() + dart_string("' has been assigned during initialization.")) {
  }
  
  LateError(String localName) : _message(dart_string("Local '") + localName.toString() + dart_string("' has been assigned during initialization.")) {
  }
  
  LateError(String fieldName) : _message(dart_string("Field '") + fieldName.toString() + dart_string("' has not been initialized.")) {
  }
  
  LateError(String localName) : _message(dart_string("Local '") + localName.toString() + dart_string("' has not been initialized.")) {
  }
  
  LateError(String fieldName) : _message(dart_string("Field '") + fieldName.toString() + dart_string("' has already been initialized.")) {
  }
  
  LateError(String localName) : _message(dart_string("Local '") + localName.toString() + dart_string("' has already been initialized.")) {
  }
  
  Any _throwFieldAlreadyInitialized(String fieldName) {
    {
      throw DartException(ObjectPtr<LateError>(new LateError(fieldName)));
}
  }
  
  Any _throwLocalNotInitialized(String localName) {
    {
      throw DartException(ObjectPtr<LateError>(new LateError(localName)));
}
  }
  
  Any _throwLocalAlreadyInitialized(String localName) {
    {
      throw DartException(ObjectPtr<LateError>(new LateError(localName)));
}
  }
  
  Any _throwLocalAssignedDuringInitialization(String localName) {
    {
      throw DartException(ObjectPtr<LateError>(new LateError(localName)));
}
  }
  
  String toString() {
    {
      auto message = this->_message;
      return !((message == nullptr)) ? dart_string("LateInitializationError: ") + message.toString() : dart_string("LateInitializationError");
}
  }
  
};

