      if (!((uri->host == this->uri->host))) return dart_bool(false);
      auto thisPort = (this->uri->port == dart_int(0)) ? dart_int(80) : this->uri->port;
      auto otherPort = (uri->port == dart_int(0)) ? dart_int(80) : uri->port;
      if (!((otherPort == thisPort))) return dart_bool(false);
