Any min(Any a, Any b) {
  {
    if ((a > b)) return b;
    if ((a < b)) return a;
    if (dart_is<Double>(b)) {
    if (dart_is<Double>(a)) {
    if ((a == dart_double(0.0))) {
    auto n = (((a + b) * a) * b);
    return dart_cast<Any>(n);
}
}
    if ((a == dart_int(0)) && b->isNegative || b->isNaN) return b;
    return a;
}
    return a;
}
}

Any max(Any a, Any b) {
  {
    if ((a > b)) return a;
    if ((a < b)) return b;
    if (dart_is<Double>(b)) {
    if (dart_is<Double>(a)) {
    if ((a == dart_double(0.0))) {
    auto n = (a + b);
    return dart_cast<Any>(n);
}
}
    if (b->isNaN) return b;
    return a;
}
    if ((b == dart_int(0)) && a->isNegative) return b;
    return a;
}
}

